// ============================================================
// Validation Helpers
// ============================================================
// ValidateEntitlements validates all fields in Entitlements according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateEntitlements(m *Entitlements) error {
	return ValidateEntitlementsWithDepth(m, 0)
}

// ValidateEntitlementsWithDepth validates Entitlements and carries nested-message depth across
// generated package boundaries.
func ValidateEntitlementsWithDepth(m *Entitlements, depth int) error {
	if m == nil {
		return nil
	}
	if depth > 24 {
		return protoerrors.NewErrMissingInvalidData(nil, "message nesting exceeds max depth of 24")
	}

	// Validate Grants (assert_max_size: 256)
	if len(m.Grants) > 256 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Grants exceeds max size of 256, got: %d", len(m.Grants))
	}

	// Validate Grants elements (default max size: 32768 bytes)
	for i, val := range m.Grants {
		if len(val) > 32768 {
			return protoerrors.NewErrMissingInvalidData(nil, "field Grants[%d] exceeds max size of 32768 bytes, got: %d", i, len(val))
		}
	}

	// Validate TraceId (default max size: 32768 bytes)
	if len(m.TraceId) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field TraceId exceeds max size of 32768 bytes, got: %d", len(m.TraceId))
	}

	return nil
}

// ValidateCredPair validates all fields in CredPair according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateCredPair(m *CredPair) error {
	return ValidateCredPairWithDepth(m, 0)
}

// ValidateCredPairWithDepth validates CredPair and carries nested-message depth across
// generated package boundaries.
func ValidateCredPairWithDepth(m *CredPair, depth int) error {
	if m == nil {
		return nil
	}
	if depth > 24 {
		return protoerrors.NewErrMissingInvalidData(nil, "message nesting exceeds max depth of 24")
	}

	// Validate Id (assert_min_size: 1 bytes)
	if len(m.Id) < 1 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Id below min size of 1 bytes, got: %d", len(m.Id))
	}

	// Validate Id (assert_required)
	if m.Id == "" {
		return protoerrors.NewErrMissingInvalidData(nil, "field Id is required")
	}

	// Validate TenantName (assert_required)
	if m.TenantName == "" {
		return protoerrors.NewErrMissingInvalidData(nil, "field TenantName is required")
	}

	// Validate PublicKey (assert_required)
	if m.PublicKey == nil {
		return protoerrors.NewErrMissingInvalidData(nil, "field PublicKey is required")
	}

	// Validate Namespaces (assert_max_size: 256)
	if len(m.Namespaces) > 256 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Namespaces exceeds max size of 256, got: %d", len(m.Namespaces))
	}

	// Validate Description (assert_max_size: 256 bytes)
	if len(m.Description) > 256 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Description exceeds max size of 256 bytes, got: %d", len(m.Description))
	}

	// Validate Namespaces elements (default max size: 32768 bytes)
	for i, val := range m.Namespaces {
		if len(val) > 32768 {
			return protoerrors.NewErrMissingInvalidData(nil, "field Namespaces[%d] exceeds max size of 32768 bytes, got: %d", i, len(val))
		}
	}

	// Validate Id (default max size: 32768 bytes)
	if len(m.Id) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Id exceeds max size of 32768 bytes, got: %d", len(m.Id))
	}

	// Validate TenantName (default max size: 32768 bytes)
	if len(m.TenantName) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field TenantName exceeds max size of 32768 bytes, got: %d", len(m.TenantName))
	}

	// Validate TraceId (default max size: 32768 bytes)
	if len(m.TraceId) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field TraceId exceeds max size of 32768 bytes, got: %d", len(m.TraceId))
	}

	// Validate PublicKey nested message
	if m.PublicKey != nil {
		if err := jwk.ValidateJwkWithDepth(m.PublicKey, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field PublicKey validation failed")
		}
	}

	// Validate Entitlements nested message
	if m.Entitlements != nil {
		if err := entitlements.ValidateTokenEntitlementsWithDepth(m.Entitlements, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field Entitlements validation failed")
		}
	}

	return nil
}

// ValidateKernelTenantConfig validates all fields in KernelTenantConfig according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateKernelTenantConfig(m *KernelTenantConfig) error {
	return ValidateKernelTenantConfigWithDepth(m, 0)
}

// ValidateKernelTenantConfigWithDepth validates KernelTenantConfig and carries nested-message depth across
// generated package boundaries.
func ValidateKernelTenantConfigWithDepth(m *KernelTenantConfig, depth int) error {
	if m == nil {
		return nil
	}
	if depth > 24 {
		return protoerrors.NewErrMissingInvalidData(nil, "message nesting exceeds max depth of 24")
	}

	// Validate CredPairs (assert_max_size: 256)
	if len(m.CredPairs) > 256 {
		return protoerrors.NewErrMissingInvalidData(nil, "field CredPairs exceeds max size of 256, got: %d", len(m.CredPairs))
	}

	// Validate TraceId (default max size: 32768 bytes)
	if len(m.TraceId) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field TraceId exceeds max size of 32768 bytes, got: %d", len(m.TraceId))
	}

	// Validate CredPairs nested messages
	for i, val := range m.CredPairs {
		if err := ValidateCredPairWithDepth(val, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field CredPairs[%d] validation failed", i)
		}
	}

	return nil
}

