// Merge: Entitlements
// ============================================================
// MergeEntitlements fills zero-valued fields in dst from src.
func MergeEntitlements(dst, src *Entitlements) {
	if len(dst.Grants) == 0 {
		dst.Grants = src.Grants
	}
	if dst.TraceId == "" {
		dst.TraceId = src.TraceId
	}
	if !dst.Noop {
		dst.Noop = src.Noop
	}
}

// ============================================================
// Merge: CredPair
// ============================================================
// MergeCredPair fills zero-valued fields in dst from src.
func MergeCredPair(dst, src *CredPair) {
	if dst.Id == "" {
		dst.Id = src.Id
	}
	if dst.TenantName == "" {
		dst.TenantName = src.TenantName
	}
	if dst.PublicKey == nil {
		dst.PublicKey = src.PublicKey
	}
	if dst.Entitlements == nil {
		dst.Entitlements = src.Entitlements
	}
	if len(dst.Namespaces) == 0 {
		dst.Namespaces = src.Namespaces
	}
	if dst.Description == "" {
		dst.Description = src.Description
	}
	if dst.CreatedAt == nil {
		dst.CreatedAt = src.CreatedAt
	}
	if dst.ExpiresAt == nil {
		dst.ExpiresAt = src.ExpiresAt
	}
	if dst.TraceId == "" {
		dst.TraceId = src.TraceId
	}
	if !dst.Noop {
		dst.Noop = src.Noop
	}
}

